import XCTest
import SwiftData
@testable import PaydayPlaybook

/// F-02 / V2-13: the five-second dashboard, assembled from production data —
/// a plan generated by the real engine and persisted by the real persister.
@MainActor
final class DashboardStateTests: XCTestCase {

    // MARK: - Five-second content

    func testDashboardShowsEveryFiveSecondFactFromGeneratedData() throws {
        let fixture = try DashboardFixtures.generatedPlan()
        let state = TodayState.load(context: fixture.context, environment: DashboardFixtures.environment())

        XCTAssertTrue(state.hasPlan)

        // Total principal remaining and percent eliminated.
        let expectedTotal = fixture.debts.reduce(Decimal.zero) { $0 + $1.startingBalance }.rounded2
        XCTAssertEqual(state.totalDebt, expectedTotal)
        XCTAssertEqual(state.startingPrincipal, expectedTotal)
        XCTAssertEqual(state.percentEliminated, .zero, "Nothing is paid yet, so nothing is eliminated.")

        // Plan status.
        if case .needsAttention = state.statusKind {
            XCTFail("A fresh plan with no entries is on track, not flagged.")
        }

        // Current target and why it is first.
        let target = try XCTUnwrap(state.targetDebt)
        XCTAssertEqual(target.debt.planID, "A", "Highest APR (29.99%) leads the avalanche.")
        let reason = try XCTUnwrap(state.targetReason)
        XCTAssertFalse(reason.isEmpty)

        // Single next action: the first payday, with its amounts.
        let next = try XCTUnwrap(state.nextItem ?? state.currentItem)
        XCTAssertEqual(next.sequenceNumber, 1)
        XCTAssertEqual(DateMath.startOfDay(next.date), TestSupport.date(2054, 8, 20))
        XCTAssertGreaterThan(next.plannedCardBudget, .zero)
        XCTAssertGreaterThan(next.plannedC2Transfer, .zero)
        XCTAssertFalse(next.plannedTargetDebtID.isEmpty)

        // Forecast payoff date and paychecks remaining.
        XCTAssertNotNil(state.forecastPayoffDate)
        XCTAssertGreaterThan(try XCTUnwrap(state.paychecksRemaining), 0)

        // Estimated remaining interest.
        XCTAssertGreaterThan(try XCTUnwrap(state.estimatedRemainingInterest), .zero)

        // Named accounts with roles, and protected-cash status.
        let spending = try XCTUnwrap(state.spendingAccount)
        XCTAssertEqual(spending.account.name, "Everyday Checking")
        XCTAssertTrue(spending.account.roles.contains(.spending))
        let reserves = try XCTUnwrap(state.reservesAccount)
        XCTAssertEqual(reserves.account.name, "Bills & Debt")
        let checking1 = try XCTUnwrap(state.checking1)
        XCTAssertEqual(checking1.protectedFloor, TestSupport.money("1500.00"))

        // Next due item across debt types, and obligation reserves.
        XCTAssertFalse(state.reserveLines.isEmpty, "Generated plans carry named obligation reserves.")
        XCTAssertEqual(
            Set(state.reserveLines.map(\.name)),
            ["Rent", "Transit pass"]
        )

        // Check-in completion state and one neutral insight.
        XCTAssertNil(state.currentCheckIn, "No payday has occurred yet.")
        let insight = try XCTUnwrap(state.insightLine)
        XCTAssertFalse(insight.isEmpty)
        XCTAssertFalse(insight.lowercased().contains("should have"), "Insights never scold.")

        // Goal copy surfaces on the dashboard.
        XCTAssertEqual(state.goalText, "Debt-free before the move")
    }

    func testDashboardNeverInventsNumbersWhenNoPlanExists() throws {
        let container = try TestSupport.makeContainer()
        let context = ModelContext(container)
        let state = TodayState.load(context: context, environment: DashboardFixtures.environment())

        XCTAssertFalse(state.hasPlan)
        XCTAssertEqual(state.totalDebt, .zero)
        XCTAssertEqual(state.startingPrincipal, .zero)
        XCTAssertNil(state.forecastPayoffDate)
        XCTAssertNil(state.paychecksRemaining)
        XCTAssertNil(state.estimatedRemainingInterest)
        XCTAssertNil(state.interestSaved)
        XCTAssertNil(state.targetDebt)
        XCTAssertFalse(state.isDebtFree, "An empty store is not a debt-free celebration.")
    }

    func testCorruptedPlanSnapshotDegradesWithAWarningNotFakeNumbers() throws {
        let fixture = try DashboardFixtures.generatedPlan()
        fixture.plan.inputSnapshotData = Data("not json".utf8)
        try fixture.context.save()

        let state = TodayState.load(context: fixture.context, environment: DashboardFixtures.environment())

        XCTAssertTrue(state.hasPlan, "The stored schedule is still the plan.")
        let warning = try XCTUnwrap(state.calculationWarning)
        XCTAssertFalse(warning.isEmpty)
        XCTAssertNil(state.interestSaved, "No comparison is claimed when inputs can't be read.")
        // The stored baseline payoff still shows — it comes from the plan row,
        // not from a recalculation.
        XCTAssertEqual(state.forecastPayoffDate, fixture.plan.baselinePayoffDate)
    }

    func testDebtFreeStateIsDerivedFromBalancesNotAnEmptyStore() throws {
        let fixture = try DashboardFixtures.generatedPlan(debtSpecs: [
            .init(planID: "A", name: "Blue Card", type: .creditCard,
                  balance: TestSupport.money("100.00"), apr: TestSupport.money("0.2000"),
                  minimum: TestSupport.money("25.00"), dueDay: 10,
                  creditLimit: TestSupport.money("1000.00"), originalPrincipal: nil)
        ])
        let debt = try XCTUnwrap(fixture.debts.first)
        fixture.context.insert(BalanceSnapshot(
            debtAccountID: debt.id,
            debtPlanID: debt.planID,
            effectiveDate: TestSupport.date(2054, 8, 9),
            amount: .zero,
            sourceType: .currentOnlineBalance,
            isAuthoritative: true
        ))
        try fixture.context.save()

        let state = TodayState.load(context: fixture.context, environment: DashboardFixtures.environment())
        XCTAssertTrue(state.isDebtFree)
        XCTAssertEqual(state.totalDebt, .zero)
    }

    // MARK: - Status and insight tone

    func testBehindPlanIsStatedPlainlyWithoutBlame() throws {
        let fixture = try DashboardFixtures.generatedPlan()
        let environment = DashboardFixtures.environment()

        // Move "today" past the first payday and record a worse-than-planned
        // balance, so the actual track is behind the plan.
        let later = AppEnvironment(dateProvider: FixedDateProvider(fixed: TestSupport.date(2054, 8, 21)))
        let debt = try XCTUnwrap(fixture.debts.first)
        fixture.context.insert(BalanceSnapshot(
            debtAccountID: debt.id,
            debtPlanID: debt.planID,
            effectiveDate: TestSupport.date(2054, 8, 21),
            amount: debt.startingBalance + TestSupport.money("500.00"),
            sourceType: .currentOnlineBalance,
            isAuthoritative: true
        ))
        try fixture.context.save()

        let state = TodayState.load(context: fixture.context, environment: later)
        guard case .behind(let amount) = state.statusKind else {
            return XCTFail("Expected the behind-plan status, got \(state.statusKind).")
        }
        XCTAssertGreaterThan(amount, .zero)
        let insight = try XCTUnwrap(state.insightLine)
        XCTAssertTrue(insight.contains("behind the plan"))
        for shaming in ["failed", "should have", "you didn't", "bad"] {
            XCTAssertFalse(insight.lowercased().contains(shaming), "Insight copy must stay neutral: \(insight)")
        }
        _ = environment
    }

    // MARK: - Legacy plan

    /// A migrated legacy plan must read back exactly as stored.
    ///
    /// The expectations come from the store's own rows rather than from
    /// constants: "the dashboard shows what was saved" is the property under
    /// test, and comparing against the rows themselves checks it directly
    /// instead of checking that two copies of the same literal agree.
    func testMigratedLegacyPlanRemainsViewableExactly() throws {
        let legacy = try DashboardFixtures.legacyMigrated()
        let state = TodayState.load(context: legacy.context, environment: DashboardFixtures.environment())

        let storedPlan = try XCTUnwrap(PlanRepository.legacyBaseline(context: legacy.context))
        let storedItems = try PlanRepository.planItems(context: legacy.context, plan: storedPlan)
        let storedDebts = try legacy.context.fetch(FetchDescriptor<DebtAccount>())
        let storedPrincipal = storedDebts.reduce(Decimal.zero) { $0 + $1.startingBalance }

        XCTAssertTrue(state.hasPlan)
        XCTAssertEqual(state.plan?.name, PlanContract.planName)
        XCTAssertEqual(state.plan?.calculationVersion, 1, "a migrated legacy plan stays calc v1")
        XCTAssertEqual(state.planItems.count, storedItems.count)
        XCTAssertGreaterThan(storedItems.count, 0)
        XCTAssertEqual(state.totalDebt, storedPrincipal)
        XCTAssertEqual(state.startingPrincipal, storedPrincipal)
        XCTAssertEqual(state.plan?.baselinePayoffDate, storedPlan.baselinePayoffDate)
        XCTAssertEqual(state.plan?.baselineModeledInterest, storedPlan.baselineModeledInterest)

        // Migrated accounts render by name with their legacy-derived balances.
        XCTAssertEqual(state.spendingAccount?.account.name, "Checking 1")
        XCTAssertEqual(state.reservesAccount?.account.name, "Checking 2")
        XCTAssertEqual(state.checking1?.protectedFloor, storedPlan.protectedBuffer)

        // The calc-v1 path claims no minimums-only comparison.
        XCTAssertNil(state.interestSaved)

        // The first payday's stored play is unchanged, value for value.
        let shown = try XCTUnwrap(state.planItems.first)
        let stored = try XCTUnwrap(storedItems.first)
        XCTAssertEqual(shown.plannedIncome, stored.plannedIncome)
        XCTAssertEqual(shown.plannedC1Keep, stored.plannedC1Keep)
        XCTAssertEqual(shown.plannedCardBudget, stored.plannedCardBudget)
        XCTAssertEqual(shown.plannedTargetDebtID, stored.plannedTargetDebtID)
    }

    func testLegacyPlanDashboardUsesLegacyReserveBucketsNotObligationRows() throws {
        let legacy = try DashboardFixtures.legacyMigrated()
        let state = TodayState.load(context: legacy.context, environment: DashboardFixtures.environment())
        let plan = try XCTUnwrap(PlanRepository.legacyBaseline(context: legacy.context))
        let first = try XCTUnwrap(state.planItems.first)
        XCTAssertEqual(first.plannedCarReserve, plan.carReservePerCheck)
        XCTAssertEqual(first.plannedTrainReserve, plan.trainReservePerCheck)
        XCTAssertGreaterThan(plan.carReservePerCheck, 0)
    }
}
